import{_ as a,o as e,c as d,ak as l}from"./chunks/framework.DKi5cyCJ.js";const g=JSON.parse('{"title":"内网 GitLab CE 部署与配置指南（精要）","description":"嵌入式团队自建 GitLab：环境、数据盘、Omnibus 安装、组织权限、备份与 FAQ","frontmatter":{"title":"内网 GitLab CE 部署与配置指南（精要）","description":"嵌入式团队自建 GitLab：环境、数据盘、Omnibus 安装、组织权限、备份与 FAQ","date":"2026-10-14T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-14-内网GitLab-CE部署与配置指南.md","filePath":"pages/blog/2026-10-14-内网GitLab-CE部署与配置指南.md"}'),i={name:"pages/blog/2026-10-14-内网GitLab-CE部署与配置指南.md"};function o(s,t,r,c,n,h){return e(),d("div",null,[...t[0]||(t[0]=[l(`<h1 id="内网-gitlab-ce-部署与配置指南-精要" tabindex="-1">内网 GitLab CE 部署与配置指南（精要） <a class="header-anchor" href="#内网-gitlab-ce-部署与配置指南-精要" aria-label="Permalink to &quot;内网 GitLab CE 部署与配置指南（精要）&quot;">​</a></h1><blockquote><p>面向嵌入式软件团队的内网 GitLab 自建说明。细节命令见「操作命令手册」。</p></blockquote><p><strong>安全约定</strong>：仅内网使用，不做公网暴露；管理员首次登录后立即改密。</p><hr><h2 id="_1-环境与拓扑" tabindex="-1">1. 环境与拓扑 <a class="header-anchor" href="#_1-环境与拓扑" aria-label="Permalink to &quot;1. 环境与拓扑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>示例值</th></tr></thead><tbody><tr><td>角色</td><td>GitLab 服务器</td></tr><tr><td>系统</td><td>Ubuntu 22.04 · Omnibus CE</td></tr><tr><td>规格</td><td>约 8C / 16G / 大容量磁盘</td></tr><tr><td>Web</td><td><code>http://&lt;GITLAB_HOST&gt;</code></td></tr><tr><td>端口</td><td>22（SSH/Git SSH）· 80（Web/HTTP Git）</td></tr></tbody></table><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">开发机<br><small>浏览器 / Git</small></div><div class="blog-flow-arrow">HTTP:80<br>SSH:22</div><div class="blog-flow-node accent">GitLab CE<br><small>Omnibus</small></div><div class="blog-flow-arrow">数据/备份</div><div class="blog-flow-node">大容量磁盘<br><small>/ 或 /data</small></div></div></div><blockquote><p>ping 通只说明 ICMP 可达。上线前仍需确认浏览器能开 80、以及能 SSH 登录服务器。</p></blockquote><hr><h2 id="_2-服务器准备-摘要" tabindex="-1">2. 服务器准备（摘要） <a class="header-anchor" href="#_2-服务器准备-摘要" aria-label="Permalink to &quot;2. 服务器准备（摘要）&quot;">​</a></h2><ol><li>基础信息查询：<code>hostnamectl</code> / <code>free -h</code> / <code>nproc</code> / <code>df -h</code> / <code>lsblk</code> / 时区</li><li>基础包：<code>curl</code>、<code>openssh-server</code>、<code>ca-certificates</code>、<code>tzdata</code>、<code>postfix</code></li><li>时区：<code>Asia/Shanghai</code></li><li>防火墙：放行 22/80（本机 ufw 或公司硬件防火墙）</li><li>确认 <strong>80 端口空闲</strong>（Omnibus 默认占 80）</li></ol><hr><h2 id="_3-数据盘策略-先判定再动手" tabindex="-1">3. 数据盘策略（先判定再动手） <a class="header-anchor" href="#_3-数据盘策略-先判定再动手" aria-label="Permalink to &quot;3. 数据盘策略（先判定再动手）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>DISK_CASE</th><th>表现</th><th>处理</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>根分区已是数 TB</td><td>用默认 <code>/var/opt/gitlab</code>，<strong>不要</strong>乱 mkfs</td></tr><tr><td><strong>B</strong></td><td>有未挂载大盘</td><td>挂到 <code>/data</code>，再改 <code>git_data_dirs</code> / <code>backup_path</code></td></tr><tr><td><strong>C</strong></td><td>大盘已挂好</td><td>在已有挂载点下建子目录并指向</td></tr></tbody></table><div class="blog-flow-col"><div class="blog-flow-node">lsblk / df -h 查看信息</div><div class="blog-flow-down">▼</div><div class="blog-flow-node">判定 DISK_CASE：A / B / C</div><div class="blog-flow-down">▼</div><div class="blog-flow-tri"><div class="blog-flow-node">A → 默认路径</div><div class="blog-flow-node">B → 挂 /data</div><div class="blog-flow-node">C → 已有挂载点</div></div><div class="blog-flow-down">▼</div><div class="blog-flow-node accent">安装 GitLab → 按需写 gitlab.rb → reconfigure</div></div><p><strong>情况 B 要点</strong>：</p><ol><li><code>mkfs</code> 会清空目标盘；</li><li>用 UUID 写 <code>/etc/fstab</code>；</li><li>建议目录 <code>/data/gitlab/git-data</code>、<code>backups</code>。<br> 首装顺序：先挂好盘 → 写好 <code>gitlab.rb</code> → 再 <code>reconfigure</code>，避免二次迁移。</li></ol><hr><h2 id="_4-安装与首次登录" tabindex="-1">4. 安装与首次登录 <a class="header-anchor" href="#_4-安装与首次登录" aria-label="Permalink to &quot;4. 安装与首次登录&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 添加官方源后</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXTERNAL_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://&lt;GITLAB_HOST&gt;&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gitlab-ce</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gitlab-ctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/gitlab/initial_root_password</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 约 24 小时内有效</span></span></code></pre></div><ol><li>浏览器打开 <code>http://&lt;GITLAB_HOST&gt;</code></li><li>用户 <code>root</code> + 初始密码登录 → <strong>立即改强密码</strong></li><li>常用：<code>gitlab-ctl status|restart|reconfigure|tail</code></li></ol><hr><h2 id="_5-管理后台与组织约定" tabindex="-1">5. 管理后台与组织约定 <a class="header-anchor" href="#_5-管理后台与组织约定" aria-label="Permalink to &quot;5. 管理后台与组织约定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>建议</th></tr></thead><tbody><tr><td>注册</td><td><strong>关闭公开注册</strong>，管理员创建或邀请</td></tr><tr><td>仓库可见性</td><td>默认 <strong>Private</strong></td></tr><tr><td>单仓大小</td><td>按磁盘设上限（如 2～5GB 起步）</td></tr><tr><td>本期可后做</td><td>HTTPS、CI Runner、LDAP、SMTP</td></tr></tbody></table><p><strong>角色</strong>：Owner（极少）→ Maintainer（负责人）→ Developer（日常）→ Reporter（只读）→ Guest</p><p><strong>分支保护建议</strong></p><table tabindex="0"><thead><tr><th>分支</th><th>建议</th></tr></thead><tbody><tr><td><code>main</code></td><td>Protected，禁止 force push，Maintainer 合并</td></tr><tr><td><code>feature/*</code></td><td>不保护，Developer 自由推</td></tr><tr><td><code>release/*</code>、Tag <code>v*</code></td><td>Protected</td></tr></tbody></table><p>Group 按产品线建；<strong>一独立编译/发布单元 = 一仓</strong>，避免巨型单体仓。</p><hr><h2 id="_6-开发机接入与嵌入式约定" tabindex="-1">6. 开发机接入与嵌入式约定 <a class="header-anchor" href="#_6-开发机接入与嵌入式约定" aria-label="Permalink to &quot;6. 开发机接入与嵌入式约定&quot;">​</a></h2><ul><li>配置 <code>user.name</code> / <code>user.email</code></li><li>推荐 SSH Key；或 HTTP + Personal Access Token（用户名常用 <code>oauth2</code>）</li><li>日常：<code>feature/*</code> → 提 Merge Request → Maintainer 合入</li></ul><table tabindex="0"><thead><tr><th>应进 Git</th><th>不建议进 Git</th></tr></thead><tbody><tr><td>源码、构建脚本、小配置</td><td><code>build/</code>、<code>*.o</code>/<code>*.elf</code> 等可重建产物</td></tr><tr><td>非机密文档</td><td>密钥、私钥、客户机密参数</td></tr><tr><td><code>.gitignore</code>（必配）</td><td>GB 级二进制（改用 LFS/制品区）</td></tr></tbody></table><hr><h2 id="_7-备份与升级" tabindex="-1">7. 备份与升级 <a class="header-anchor" href="#_7-备份与升级" aria-label="Permalink to &quot;7. 备份与升级&quot;">​</a></h2><p>完整恢复至少需要：</p><ol><li><code>gitlab-backup create</code> 备份包</li><li><code>/etc/gitlab/gitlab.rb</code></li><li><code>/etc/gitlab/gitlab-secrets.json</code>（丢失可能无法解密部分数据）</li></ol><p>建议 cron 定时备份，并另拷一份到其它机器。升级只走官方路径，<strong>禁止跨多版本一次跳</strong>；升级前完整备份并通知暂停 push。</p><hr><h2 id="_8-上线验收清单-摘要" tabindex="-1">8. 上线验收清单（摘要） <a class="header-anchor" href="#_8-上线验收清单-摘要" aria-label="Permalink to &quot;8. 上线验收清单（摘要）&quot;">​</a></h2><ul><li>[ ] SSH / Web 可访问，管理员密码已改</li><li>[ ] 公开注册已关；DISK_CASE 已确认</li><li>[ ] Group/Project/保护分支就绪</li><li>[ ] 至少一台开发机 clone/push 成功</li><li>[ ] 已做过一次手动备份</li></ul><hr><h2 id="附件-·-cursor-skills-可下载" tabindex="-1">附件 · Cursor Skills（可下载） <a class="header-anchor" href="#附件-·-cursor-skills-可下载" aria-label="Permalink to &quot;附件 · Cursor Skills（可下载）&quot;">​</a></h2><p>本流程对应 Agent 可执行模块（放在项目 <code>.cursor/skills/</code>，也可直接下载 zip）：</p><table tabindex="0"><thead><tr><th>附件</th><th>说明</th></tr></thead><tbody><tr><td><a href="/assets/attachments/gitlab-local-skills.zip">gitlab-local-skills.zip</a></td><td><code>gitlab-local-00</code>～<code>07</code> 全套 Skill</td></tr><tr><td><a href="/assets/attachments/gitlab-skills/">Skills 目录浏览</a></td><td>解压后的目录结构</td></tr><tr><td><a href="/assets/attachments/gitlab-skills/Skills-index.html">Skills索引.md</a></td><td>顺序与话术</td></tr></tbody></table><p>换服务器：先改 <code>gitlab-local-00-orchestrate/env-template.md</code>，再按 01→07 执行。</p>`,45)])])}const p=a(i,[["render",o]]);export{g as __pageData,p as default};
